document.addEventListener('DOMContentLoaded', () => {
    const refreshBtn = document.getElementById('refreshBtn');
    const loader = document.getElementById('loader');
    const dashboardContent = document.getElementById('dashboardContent');
    const conjunctionTableBody = document.getElementById('conjunctionTableBody');
    const errorState = document.getElementById('errorState');
    const errorMessage = document.getElementById('errorMessage');

    // Backend API URL
    const API_URL = 'http://127.0.0.1:8000/api/conjunctions';

    const fetchConjunctionData = async () => {
        // UI Reset
        loader.classList.remove('hidden');
        dashboardContent.classList.add('hidden');
        errorState.classList.add('hidden');
        conjunctionTableBody.innerHTML = '';

        try {
            const response = await fetch(API_URL);

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const data = await response.json();

            if (data.conjunctions && data.conjunctions.length > 0) {
                renderTable(data.conjunctions);
                dashboardContent.classList.remove('hidden');
            } else {
                showError("No conjunction data found.");
            }
        } catch (error) {
            console.error("Error fetching data:", error);
            showError("Failed to connect to the backend server. Is it running?");
        } finally {
            loader.classList.add('hidden');
        }
    };

    const renderTable = (conjunctions) => {
        conjunctions.forEach(item => {
            const row = document.createElement('tr');
            row.className = 'hover:bg-gray-750 transition duration-150';

            // Risk Level Styling
            let riskBadgeClass = '';
            if (item.risk_level === 'High') {
                riskBadgeClass = 'bg-red-900/50 text-red-400 border border-red-500/50 px-2 py-1 rounded text-xs font-semibold';
            } else if (item.risk_level === 'Medium') {
                riskBadgeClass = 'bg-yellow-900/50 text-yellow-400 border border-yellow-500/50 px-2 py-1 rounded text-xs font-semibold';
            } else {
                riskBadgeClass = 'bg-green-900/50 text-green-400 border border-green-500/50 px-2 py-1 rounded text-xs font-semibold';
            }

            const date = new Date(item.closest_approach_time);
            const formattedDate = date.toLocaleString('en-US', { timeZone: 'UTC', timeZoneName: 'short' });

            row.innerHTML = `
                <td class="p-4 border-b border-gray-700 font-medium">${item.object1}</td>
                <td class="p-4 border-b border-gray-700 font-medium">${item.object2}</td>
                <td class="p-4 border-b border-gray-700 text-gray-300">${formattedDate}</td>
                <td class="p-4 border-b border-gray-700 font-mono">${item.min_distance_km.toFixed(2)}</td>
                <td class="p-4 border-b border-gray-700">
                    <span class="${riskBadgeClass}">${item.risk_level}</span>
                </td>
            `;
            conjunctionTableBody.appendChild(row);
        });
    };

    const showError = (message) => {
        errorMessage.textContent = message;
        errorState.classList.remove('hidden');
    };

    // Initial fetch
    fetchConjunctionData();

    // Attach event listener
    refreshBtn.addEventListener('click', fetchConjunctionData);
});
